package com.arena.login.controller;
import com.arena.login.service.TokenService;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.*;
import org.springframework.http.*;
import org.springframework.mock.web.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.net.URI;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

class PublicCheckinProxyTest {
 @Test void publicCheckinForwardsNoStaffTokenCookiesOrPrivateResponse()throws Exception{
  var core=mock(RestTemplate.class);var tokens=mock(TokenService.class);var controller=new TokenController(tokens,core);ReflectionTestUtils.setField(controller,"coreUrl","http://example.invalid");ReflectionTestUtils.setField(controller,"publicClubHost",new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.test"));
  var request=new MockHttpServletRequest("POST","/api/public/facility-check-ins/submit");request.addHeader("Host","speed.arenaops.test");request.setContentType("application/json");request.setContent("{\"token\":\"test\"}".getBytes());request.addHeader("Authorization","Bearer caller-supplied");request.addHeader("Cookie","private=secret");
  var session=new MockHttpSession();session.setAttribute("ACCESS_TOKEN","staff-session");
  when(core.exchange(any(URI.class),eq(HttpMethod.POST),any(HttpEntity.class),eq(byte[].class))).thenReturn(ResponseEntity.status(201).body("{\"status\":\"PENDING\"}".getBytes()));
  assertEquals(201,controller.proxyRequest(request,session).getStatusCode().value());
  var entity=org.mockito.ArgumentCaptor.forClass(HttpEntity.class);verify(core).exchange(any(URI.class),eq(HttpMethod.POST),entity.capture(),eq(byte[].class));assertFalse(entity.getValue().getHeaders().containsKey("Authorization"));assertFalse(entity.getValue().getHeaders().containsKey("Cookie"));verifyNoInteractions(tokens);
 }
 @Test void anonymousPublicRouteDoesNotRequireBffSessionToken()throws Exception{
  var core=mock(RestTemplate.class);var controller=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(controller,"coreUrl","http://example.invalid");ReflectionTestUtils.setField(controller,"publicClubHost",new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.test"));var request=new MockHttpServletRequest("POST","/api/public/facility-check-ins/inspect");request.addHeader("Host","speed.arenaops.test");request.setContentType("application/json");request.setContent("{}".getBytes());when(core.exchange(any(URI.class),eq(HttpMethod.POST),any(HttpEntity.class),eq(byte[].class))).thenReturn(ResponseEntity.ok("{}".getBytes()));assertEquals(200,controller.proxyRequest(request,new MockHttpSession()).getStatusCode().value());
 }
 @Test void publicRootAliasRateLimitCannotBeBypassedAndIgnoresForwardedHeader()throws Exception{
  var filter=new com.arena.login.config.PublicCheckinRateLimit(new com.arena.login.exception.ApiErrors(new com.fasterxml.jackson.databind.ObjectMapper()));int[] reached={0};
  for(int i=0;i<21;i++){var req=new MockHttpServletRequest("POST",i%2==0?"/api/public/facility-check-ins/submit":"/public/facility-check-ins/submit");req.setRemoteAddr("192.0.2.1");req.addHeader("X-Forwarded-For","192.0.2."+i);req.setContent("{}".getBytes());var res=new MockHttpServletResponse();filter.doFilter(req,res,(a,b)->reached[0]++);if(i==20){assertEquals(429,res.getStatus());assertTrue(res.getContentAsString().contains("TOO_MANY_REQUESTS"));assertEquals("no-store",res.getHeader("Cache-Control"));}}
  assertEquals(20,reached[0]);
 }

 @Test void signsOnlyCanonicalHostAndIgnoresForwardedSpoofing(){var signer=new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.test");var req=new MockHttpServletRequest();req.addHeader("Host","SPEED.arenaops.test:8443");req.addHeader("X-Forwarded-Host","other.arenaops.test");var h=new HttpHeaders();h.set("X-Arena-Public-Host","attacker");signer.sign(req,h);assertEquals("speed.arenaops.test",h.getFirst("X-Arena-Public-Host"));assertEquals(64,h.getFirst("X-Arena-Public-Signature").length());}
 @Test void invalidOrMissingHostnameAndDisabledKeyRejectBeforeForwarding(){for(String host:new String[]{"arenaops.test","speed.evil.test","speed.arenaops.test.evil","a.speed.arenaops.test","speed.arenaops.test/path","speed.arenaops.test@evil"}){var req=new MockHttpServletRequest();req.addHeader("Host",host);assertThrows(RuntimeException.class,()->new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.test").sign(req,new HttpHeaders()));}var req=new MockHttpServletRequest();req.addHeader("Host","speed.arenaops.test");assertThrows(RuntimeException.class,()->new com.arena.login.service.PublicClubProxyHost("","arenaops.test").sign(req,new HttpHeaders()));}
 @Test void anonymousWebsiteProxyDoesNotCreateSessionOrSendAuthentication()throws Exception{var core=mock(RestTemplate.class);var controller=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(controller,"coreUrl","http://example.invalid");ReflectionTestUtils.setField(controller,"publicClubHost",new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.test"));var req=new MockHttpServletRequest("GET","/public/club");req.addHeader("Host","speed.arenaops.test");req.addHeader("X-Arena-Public-Signature","forged");when(core.exchange(any(URI.class),eq(HttpMethod.GET),any(HttpEntity.class),eq(byte[].class))).thenReturn(ResponseEntity.ok("{}".getBytes()));controller.proxyRequest(req);assertNull(req.getSession(false));var entity=org.mockito.ArgumentCaptor.forClass(HttpEntity.class);verify(core).exchange(any(URI.class),eq(HttpMethod.GET),entity.capture(),eq(byte[].class));assertNotEquals("forged",entity.getValue().getHeaders().getFirst("X-Arena-Public-Signature"));assertFalse(entity.getValue().getHeaders().containsKey("Cookie"));}

 com.arena.login.service.PublicClubProxyHost previewSigner(String env,boolean enabled){var signer=new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.in");ReflectionTestUtils.setField(signer,"environment",env);ReflectionTestUtils.setField(signer,"previewEnabled",enabled);return signer;}
 @Test void localPathAndHostnamePreviewSignSameTenant(){for(String host:new String[]{"localhost:4200","shradha.localhost:4200","192.168.0.219:4200"}){var r=new MockHttpServletRequest("GET","/api/public/club");r.addHeader("Host",host);if(!host.startsWith("shradha."))r.addHeader("X-Arena-Preview-Slug","shradha");var h=new HttpHeaders();previewSigner("dev",true).sign(r,h);assertEquals("shradha.arenaops.in",h.getFirst("X-Arena-Public-Host"));}}
 @Test void pathPreviewFailsClosedInProductionDisabledModeWrongHostAndQrRoutes(){for(String env:new String[]{"prod","unknown"}){var r=new MockHttpServletRequest("GET","/api/public/club");r.addHeader("Host","localhost:4200");r.addHeader("X-Arena-Preview-Slug","shradha");assertThrows(RuntimeException.class,()->previewSigner(env,true).sign(r,new HttpHeaders()));}for(String path:new String[]{"/api/public/club","/api/public/facility-check-ins/inspect"}){var r=new MockHttpServletRequest("GET",path);r.addHeader("Host","localhost:4200");r.addHeader("X-Arena-Preview-Slug","shradha");assertThrows(RuntimeException.class,()->previewSigner("dev",false).sign(r,new HttpHeaders()));if(path.contains("check-ins"))assertThrows(RuntimeException.class,()->previewSigner("dev",true).sign(r,new HttpHeaders()));}var r=new MockHttpServletRequest("GET","/api/public/club");r.addHeader("Host","evil.invalid");r.addHeader("X-Arena-Preview-Slug","shradha");assertThrows(RuntimeException.class,()->previewSigner("dev",true).sign(r,new HttpHeaders()));}
 @Test void sitPreviewIsBoundToSitHostAndLocalHostnameCannotBeOverridden(){var r=new MockHttpServletRequest("GET","/public/club");r.addHeader("Host","sit.arenaops.in");r.addHeader("X-Arena-Preview-Slug","speed");var h=new HttpHeaders();previewSigner("sit",true).sign(r,h);assertEquals("speed.arenaops.in",h.getFirst("X-Arena-Public-Host"));var mismatch=new MockHttpServletRequest("GET","/public/club");mismatch.addHeader("Host","speed.localhost:4200");mismatch.addHeader("X-Arena-Preview-Slug","shradha");assertThrows(RuntimeException.class,()->previewSigner("dev",true).sign(mismatch,new HttpHeaders()));}

 @Test void reservationForwardingKeepsLocalTimePayloadAndSafeSpecificValidationCode()throws Exception{var core=mock(RestTemplate.class);var controller=new TokenController(mock(TokenService.class),core);ReflectionTestUtils.setField(controller,"coreUrl","http://example.invalid");ReflectionTestUtils.setField(controller,"publicClubHost",previewSigner("dev",true));var request=new MockHttpServletRequest("POST","/api/public/club/reservations");request.addHeader("Host","192.168.0.219:4200");request.addHeader("X-Arena-Preview-Slug","shradha");request.setContentType("application/json");byte[] payload="{\"start\":\"2026-11-05T12:07\",\"mobile\":\"+919876543210\"}".getBytes();request.setContent(payload);when(core.exchange(any(URI.class),eq(HttpMethod.POST),any(HttpEntity.class),eq(byte[].class))).thenThrow(HttpClientErrorException.create(HttpStatus.BAD_REQUEST,"bad",new HttpHeaders(),"{\"errorCode\":\"PUBLIC_BOOKING_TIME_INCREMENT\",\"description\":\"private database detail\"}".getBytes(),java.nio.charset.StandardCharsets.UTF_8));var reply=controller.proxyRequest(request);assertEquals(400,reply.getStatusCode().value());String body=new String(reply.getBody());assertTrue(body.contains("PUBLIC_BOOKING_TIME_INCREMENT"));assertTrue(body.contains(":00, :15, :30 or :45"));assertFalse(body.contains("database detail"));var entity=org.mockito.ArgumentCaptor.forClass(HttpEntity.class);verify(core).exchange(any(URI.class),eq(HttpMethod.POST),entity.capture(),eq(byte[].class));assertArrayEquals(payload,(byte[])entity.getValue().getBody());assertFalse(entity.getValue().getHeaders().containsKey("Authorization"));assertFalse(entity.getValue().getHeaders().containsKey("X-Arena-Preview-Slug"));}
 @Test void localCheckinTenantSelectorIsIndependentOfWebsitePreviewFlag(){for(String path:new String[]{"/api/public/facility-check-ins/inspect","/api/public/facility-check-ins/submit"}){var r=new MockHttpServletRequest("POST",path);r.addHeader("Host","192.168.0.219:4200");r.addHeader("X-Arena-Preview-Slug","shradha");var h=new HttpHeaders();previewSigner("dev",true).sign(r,h);assertEquals("shradha.arenaops.in",h.getFirst("X-Arena-Public-Host"));assertThrows(RuntimeException.class,()->previewSigner("prod",true).sign(r,new HttpHeaders()));var independent=new HttpHeaders();previewSigner("dev",false).sign(r,independent);assertEquals("shradha.arenaops.in",independent.getFirst("X-Arena-Public-Host"));}}
 @Test void sitCustomerCheckinUsesSignedTenantWithoutWildcardHost(){for(String path:new String[]{"/api/public/facility-check-ins/inspect","/api/public/facility-check-ins/submit"}){var r=new MockHttpServletRequest("POST",path);r.addHeader("Host","sit.arenaops.in");r.addHeader("X-Arena-Preview-Slug","shradha");var h=new HttpHeaders();previewSigner("sit",true).sign(r,h);assertEquals("shradha.arenaops.in",h.getFirst("X-Arena-Public-Host"));assertNotNull(h.getFirst("X-Arena-Public-Signature"));}}

 @Test void sharedCheckinHostsDoNotRequireWebsitePreviewFlag(){for(String host:java.util.List.of("localhost:4200","192.168.0.219:4200","172.20.1.4:4200","sit.arenaops.test","arenaops.test")){var signer=new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.test");ReflectionTestUtils.setField(signer,"environment",host.startsWith("sit.")?"sit":host.equals("arenaops.test")?"prod":"dev");ReflectionTestUtils.setField(signer,"previewEnabled",false);var request=new MockHttpServletRequest("POST","/api/public/facility-check-ins/inspect");request.addHeader("Host",host);var headers=new HttpHeaders();signer.sign(request,headers);assertEquals("arenaops.test",headers.getFirst("X-Arena-Public-Host"));assertNotNull(headers.getFirst("X-Arena-Public-Signature"));}}
 @Test void sharedCheckinDoesNotEnableWebsiteRoutesArbitraryHostsOrMethods(){var signer=new com.arena.login.service.PublicClubProxyHost("12345678901234567890123456789012","arenaops.test");ReflectionTestUtils.setField(signer,"environment","dev");for(String path:java.util.List.of("/api/public/club","/api/public/club/reservations","/api/public/anything")){var request=new MockHttpServletRequest("POST",path);request.addHeader("Host","localhost:4200");assertThrows(RuntimeException.class,()->signer.sign(request,new HttpHeaders()));}for(String host:java.util.List.of("evil.invalid","speed.arenaops.test.evil")){var request=new MockHttpServletRequest("POST","/api/public/facility-check-ins/inspect");request.addHeader("Host",host);assertThrows(RuntimeException.class,()->signer.sign(request,new HttpHeaders()));}var get=new MockHttpServletRequest("GET","/api/public/facility-check-ins/inspect");get.addHeader("Host","localhost:4200");assertThrows(RuntimeException.class,()->signer.sign(get,new HttpHeaders()));}
}
